from fractions import Fraction as F
from math import factorial,log
def bn(n,k):
 r=F(1)
 for i in range(k):r*=F(n-i,i+1)
 return r
def col(g,a,s,q=3):
 h={-a-g+j:F(factorial(g))*bn(-a,g-j)*bn(a-4,j)*(-1)**j for j in range(g+1)};Q=q+2;z=-1 if s=='-' else 1;o={}
 for e,x in h.items():
  v=e+1+z*Q;o[e]=o.get(e,F())+x*v;o[e+1]=o.get(e+1,F())+x*(v-g)
 o={e:x for e,x in o.items() if x};return o if s=='-' else {e+Q:-x for e,x in o.items()}
def sub(v,w,z):
 for e,x in w.items():
  v[e]=v.get(e,F())-z*x
  if not v[e]:del v[e]
def run(g,N=120):
 E=[];R=[];P=[];B=[];D={}
 for a in range(N+1):
  for s in '-+':
   v=col(g,a,s);r={}
   for i,p in enumerate(P):
    z=v.get(p,F())
    if z:
     sub(v,E[i],z)
     for j,x in R[i].items():r[j]=r.get(j,F())-z*x
   if v:
    p=min(v);z=v[p];E.append({e:x/z for e,x in v.items()});r={j:x/z for j,x in r.items()};r[len(P)]=F(1,z);R.append(r);P.append(p);B.append((a,s))
   else:D[(a,s)]={j:-x for j,x in r.items()}
 vals=[]
 for K in [80,120]:
  rows=[F()]*len(B);cs=[]
  for (a,s),r in D.items():
   if s!='+' or a>K:continue
   cs.append(sum(map(abs,r.values())))
   for j,x in r.items():rows[j]+=abs(x)
  vals.append((float(max(cs)),float(max(rows))))
 ec=log(vals[1][0]/vals[0][0])/log(1.5);er=log(vals[1][1]/vals[0][1])/log(1.5)
 print(g,*(f'{x:.3g}' for v in vals for x in v),f'deg={ec:.3f},{er:.3f}')
for g in range(3,9):run(g)
